import hashlib

def h(s):
    """SHA-1 di una stringa come intero a 160 bit."""
    return int.from_bytes(hashlib.sha1(s.encode()).digest(), "big")

def frazione_spostata(keys, n_old, n_new):
    moved = sum(1 for k in keys if k % n_old != k % n_new)
    return moved / len(keys)

keys = [h(f"url-{i}") for i in range(20000)]
from math import lcm

def teoria(a, b):
    L = lcm(a, b)                      # k mod L determina entrambi i resti
    ferme = sum(1 for r in range(L) if r % a == r % b)
    return 1 - ferme / L

for a, b in [(4, 6), (4, 3), (10, 11), (100, 101)]:
    print(f"{a:>3} -> {b:>3} server: spostate {frazione_spostata(keys, a, b):.1%}"
          f"  (teoria {teoria(a, b):.1%})")

