def succ(nodes, x, N):
    x %= N
    cand = [n for n in sorted(nodes) if n >= x]
    return cand[0] if cand else min(nodes)

def assegna(nodes, items, N):
    return {name: succ(nodes, k, N) for name, k in items.items()}

N = 16
nodes = {0, 2, 5, 6, 11}
items = {"scudo": 12, "ascia": 2, "corona": 9, "spada": 14, "anello": 4}
prima = assegna(nodes, items, N)
print("prima:", prima)
dopo = assegna(nodes - {11}, items, N)
print("dopo leave 11:", dopo)
print("spostati:", [k for k in items if prima[k] != dopo[k]])
dopo_join = assegna(nodes | {13}, items, N)
print("dopo join 13:", dopo_join)
print("spostati:", [k for k in items if prima[k] != dopo_join[k]])

